using System.ComponentModel.DataAnnotations;
using System.ComponentModel.DataAnnotations.Schema;

namespace ModularCA.Shared.Entities;

/// <summary>
/// One API key of an integration: the infrastructure API or the cert-manager issuer. An
/// integration can have several, each named for the client that holds it, so one client's key is
/// replaced or revoked without touching the others. The key itself is generated by the server,
/// shown once and not kept: the row holds its SHA-256.
/// </summary>
[Table("ApiKeys")]
public class ApiKeyEntity
{
    [Key]
    public Guid Id { get; set; } = Guid.NewGuid();

    /// <summary>Which integration the key opens: see <c>ApiKeyIntegrations</c>.</summary>
    [MaxLength(32)]
    public string Integration { get; set; } = string.Empty;

    /// <summary>What an administrator calls the key, usually the client that holds it.</summary>
    [MaxLength(100)]
    public string Name { get; set; } = string.Empty;

    /// <summary>SHA-256 of the key. The key is 256 random bits, so a plain hash is enough.</summary>
    [MaxLength(32)]
    public byte[] KeyHash { get; set; } = [];

    /// <summary>The last four characters of the key, so an administrator can tell which one a client holds.</summary>
    [MaxLength(8)]
    public string Hint { get; set; } = string.Empty;

    /// <summary>
    /// The CAs the key reaches, in the form <c>IntegrationSpaceScope</c> parses: a space id,
    /// <c>instance</c>, or null for whatever the integration itself is allowed.
    /// </summary>
    [MaxLength(64)]
    public string? SpaceScope { get; set; }

    public DateTime CreatedAt { get; set; } = DateTime.UtcNow;

    public Guid? CreatedByUserId { get; set; }

    [MaxLength(256)]
    public string CreatedByName { get; set; } = string.Empty;

    /// <summary>When the key stops working by itself; null for never.</summary>
    public DateTime? ExpiresAt { get; set; }

    /// <summary>When the key was revoked; null while it works. A revoked key is kept, for the record of what it was.</summary>
    public DateTime? RevokedAt { get; set; }

    [MaxLength(256)]
    public string? RevokedByName { get; set; }

    /// <summary>When the key last opened a request, to within a few minutes; null when it never has.</summary>
    public DateTime? LastUsedAt { get; set; }
}
